import requests
import time
from .cbts import CloudBTS


class SiteHandler(object):
    @staticmethod
    def wait_for_site_availability(url, timeout, interval=1.0):
        return SiteHandler.wait_for_desired_site_state(url, timeout,
                                                       is_in_desired_state=lambda reachable: reachable,
                                                       interval=interval)

    @staticmethod
    def wait_for_site_unavailability(url, timeout, interval=1.0):
        return SiteHandler.wait_for_desired_site_state(url, timeout,
                                                       is_in_desired_state=lambda reachable: not reachable,
                                                       interval=interval)

    @staticmethod
    def wait_for_desired_site_state(url, timeout, is_in_desired_state, interval=1.0):
        """
        Waits until site under given url is in desired state or timeout expires.

        :param url: site url
        :param timeout: time to wait for site to go down, timeout should be
        greater or equal to 1
        :param is_in_desired_state: function that returns bool given `is-reachable` status
        :param interval: time in seconds between checks
        :return: True if site is in desired state, False otherwise
        """
        site_in_desired_state = False
        end = time.time() + timeout
        while not _timeout_expired(end):
            is_reachable = SiteHandler.server_is_reachable(url, timeout=1)
            site_in_desired_state = is_in_desired_state(is_reachable)
            if site_in_desired_state:
                break
            time.sleep(interval)

        return site_in_desired_state

    @staticmethod
    def reset_site(session_handler):
        """ Performs site reset. """
        return CloudBTS(session_handler).reset_site()

    @staticmethod
    def reset_and_wait_for_site(session_handler, unavailability_timeout=60, availability_timeout=600):
        """
        Performs site reset, waits until site is unreachable or timeout expires
        and then waits until site is reachable or timeout expires.

        :param session_handler: session
        :param unavailability_timeout: time in seconds to wait for site unavailability, timeout should be
        grater or equal to 1, defaults to 60
        :param availability_timeout: time in seconds to wait for site availability, timeout should be
        grater or equal to 1, defaults to 600
        """
        SiteHandler.reset_site(session_handler)
        url = session_handler.session.url
        SiteHandler.wait_for_site_unavailability(url, unavailability_timeout)
        SiteHandler.wait_for_site_availability(url, availability_timeout)

    @staticmethod
    def server_is_reachable(url, timeout):
        try:
            response = requests.get(url, verify=False, timeout=timeout)
            return response.ok
        except requests.exceptions.ConnectionError:
            return False
        except requests.exceptions.ReadTimeout:
            return False


def _timeout_expired(end):
    return end < time.time()
